	long accumulateLaneDiagnostics(FrontierLeafSelector selector, int direction,
			long[] designMatchedRows, double[] designWeightedRows,
			long[] auditMatchedRows, double[] auditWeightedRows) {
		if (direction != FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION
				&& direction != FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION) {
			throw new IllegalArgumentException("invalid Frontier query-index direction");
		}
		long scannedRows = 0L;
		for (int laneIndex = 0; laneIndex < designMatchedRows.length; laneIndex++) {
			scannedRows = Math.addExact(
					scannedRows,
					accumulateLaneDiagnostics(
							selector,
							direction,
							FrontierManifestIdentity.DESIGN_LANE_ROLE,
							laneIndex,
							designMatchedRows,
							designWeightedRows));
		}
		for (int laneIndex = 0; laneIndex < auditMatchedRows.length; laneIndex++) {
			scannedRows = Math.addExact(
					scannedRows,
					accumulateLaneDiagnostics(
							selector,
							direction,
							FrontierManifestIdentity.AUDIT_LANE_ROLE,
							laneIndex,
							auditMatchedRows,
							auditWeightedRows));
		}
		return scannedRows;
	}

	LeafScanProgress visitLeafOnce(
			FrontierLeafSelector selector,
			int direction,
			long maximumScannedRows,
			boolean includeIndependentLanes,
			boolean retainIndependentDesign,
			long[] designMatchedRows,
			double[] designWeightedRows,
			long[] auditMatchedRows,
			double[] auditWeightedRows,
			FrontierQueryIndexRowSink primaryDesignSink,
			FrontierQueryIndexRowSink independentDesignSink) {
		if (maximumScannedRows < 0L) {
			throw new IllegalArgumentException("maximumScannedRows must be nonnegative");
		}
		if (direction != FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION
				&& direction != FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION) {
			throw new IllegalArgumentException("invalid Frontier query-index direction");
		}
		long scannedRows = 0L;
		int designLaneLimit = includeIndependentLanes ? designMatchedRows.length
				: Math.min(1,
						designMatchedRows.length);
		for (int laneIndex = 0; laneIndex < designLaneLimit; laneIndex++) {
			LeafScanProgress progress = visitLeafScope(
					selector,
					direction,
					FrontierManifestIdentity.DESIGN_LANE_ROLE,
					laneIndex,
					maximumScannedRows - scannedRows,
					designMatchedRows,
					designWeightedRows,
					primaryDesignSink,
					independentDesignSink,
					retainIndependentDesign);
			scannedRows = Math.addExact(scannedRows, progress.scannedRows);
			if (!progress.complete) {
				return new LeafScanProgress(scannedRows, false);
			}
		}
		if (includeIndependentLanes) {
			for (int laneIndex = 0; laneIndex < auditMatchedRows.length; laneIndex++) {
				LeafScanProgress progress = visitLeafScope(
						selector,
						direction,
						FrontierManifestIdentity.AUDIT_LANE_ROLE,
						laneIndex,
						maximumScannedRows - scannedRows,
						auditMatchedRows,
						auditWeightedRows,
						primaryDesignSink,
						independentDesignSink,
						false);
				scannedRows = Math.addExact(scannedRows, progress.scannedRows);
				if (!progress.complete) {
					return new LeafScanProgress(scannedRows, false);
				}
			}
		}
		return new LeafScanProgress(scannedRows, true);
	}

	boolean containsExactCenter(int direction, int laneRole, int laneIndex, long centerId) {
		requireScope(direction, laneRole, laneIndex);
		if (centerId <= 0L) {
			return false;
		}
		int component = direction == FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION ? 0 : 2;
		Range range = equalRange(component, direction, laneRole, laneIndex, centerId);
		for (long position = range.from; position < range.to; position++) {
			int row = rowId(component, position);
			if (metadata(METADATA_DATABASE_EXACT, row) != 0) {
				return true;
			}
		}
		return false;
	}

